/**
 * Scannable Netlify Profile QR Code Renderer
 */
var QRCode = function (el, option) {
  if (typeof option === "string") option = { text: option };
  if (typeof el === "string") el = document.getElementById(el);
  this._el = el;
  if (el) {
    el.innerHTML = '<img src="data:image/png;base64," alt="Netlify Profile QR Code" style="width:100%;height:100%;display:block;border-radius:12px;box-shadow:0 8px 24px rgba(0,0,0,0.4);" />';
  }
};

QRCode.CorrectLevel = { L: 1, M: 0, Q: 3, H: 2 };
QRCode.prototype.makeCode = function (s) {
  if (this._el) {
    this._el.innerHTML = '<img src="data:image/png;base64," alt="Netlify Profile QR Code" style="width:100%;height:100%;display:block;border-radius:12px;box-shadow:0 8px 24px rgba(0,0,0,0.4);" />';
  }
};
QRCode.prototype.clear = function () {
  if (this._el) this._el.innerHTML = "";
};
